# Named here rather than generated by Django, so it is the same constraint on every database.
CASCADE_CONSTRAINT = "oauth_applicationexemption_application_id_cascade"


def add_cascading_foreign_key(apps, schema_editor):
    """apps/oauth/models.py turns off Django's constraint on ApplicationExemption.application. This one cascades
    in the database, so a release that doesn't know ApplicationExemption can still delete an exempt application,
    or its owner's account."""
    exemption = apps.get_model("oauth", "ApplicationExemption")
    field = exemption._meta.get_field("application")
    quote = schema_editor.quote_name
    schema_editor.execute(
        "ALTER TABLE %s ADD CONSTRAINT %s FOREIGN KEY (%s) REFERENCES %s (%s) "
        "ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED"
        % (
            quote(exemption._meta.db_table),
            quote(CASCADE_CONSTRAINT),
            quote(field.column),
            quote(field.related_model._meta.db_table),
            quote(field.target_field.column),
        )
    )


def exempt_applications(apps, schema_editor):
    exempt_existing_applications(apps, schema_editor.connection.alias)


